 public ComponentHub(Box owner,DockBar bar,bool simulated=false){box=owner;dock=bar;test=simulated;path=Path.Combine(Program.S.Root,"components.json");if(File.Exists(path))try{Options=new JavaScriptSerializer().Deserialize<ComponentOptions>(File.ReadAllText(path));if(Options==null||Options.Items==null)throw new InvalidDataException();}catch{throw new InvalidDataException("组件配置读取失败，原文件保留，请检查 components.json");}if(Double.IsNaN(Options.Glass)||Double.IsInfinity(Options.Glass))Options.Glass=50;Options.Glass=Math.Max(0,Math.Min(100,Options.Glass));bool[] enabled={Program.S.Data.StatusVisible,box.IsVisible,Program.Control!=null&&Program.Control.VisiblePreference,Program.Shots==null||Program.Shots.Store.Data.Visible,true,Program.Files==null||Program.Files.Options.Visible};string[] keys={"Ctrl+Alt+1","F5","Ctrl+Alt+2","Shift+F4","Ctrl+Alt+4",""};for(int i=0;i<Ids.Length;i++)if(!Options.Items.ContainsKey(Ids[i])||Options.Items[Ids[i]]==null)Options.Items[Ids[i]]=new ComponentOption{Enabled=enabled[i],Shortcut=keys[i]};
