 public void Apply(){applying=true;try{foreach(string id in Ids){var existing=WindowFor(id);if(Enabled(id)&&existing!=null&&existing.IsVisible)continue;SetVisibleCore(id,Enabled(id));}foreach(string id in Ids){Window window=WindowFor(id);if(window!=null)ComponentSizer.Restore(window,id);}Save();}finally{applying=false;}}
 public Window WindowFor(string id){switch(id){case "clock":return Program.Status;case "panel":return box;case "control":return Program.Control;case "shots":return Program.Shots;case "files":return Program.Files;default:return dock;}}
