 public static bool Parse(string text,out uint modifiers,out uint key){modifiers=0x4000;key=0;if(String.IsNullOrWhiteSpace(text))return true;try{var gesture=(KeyGesture)new KeyGestureConverter().ConvertFromInvariantString(text);if(gesture==null||gesture.Key==Key.None||(gesture.Modifiers&ModifierKeys.Windows)!=0)return false;if(gesture.Modifiers==ModifierKeys.None&&(gesture.Key<Key.F1||gesture.Key>Key.F24))return false;if((gesture.Modifiers&ModifierKeys.Control)!=0)modifiers|=2;if((gesture.Modifiers&ModifierKeys.Alt)!=0)modifiers|=1;if((gesture.Modifiers&ModifierKeys.Shift)!=0)modifiers|=4;key=(uint)KeyInterop.VirtualKeyFromKey(gesture.Key);return key>0;}catch{return false;}}
 static bool SameShortcut(string first,string second){uint fm,fk,sm,sk;return Parse(first,out fm,out fk)&&Parse(second,out sm,out sk)&&fm==sm&&fk==sk;}
 bool BindKey(int hotkeyId,string shortcut,out string error){error="";uint mods,key;if(!Parse(shortcut,out mods,out key)){error="请选择功能键或 Ctrl / Alt / Shift 组合键";return false;}if((mods==0x4000&&(key==0x73||key==0x75||key==0x7b))){error="F4、F6、F12 已有固定用途";return false;}if(key!=0){foreach(var pair in registered)if(pair.Key!=hotkeyId&&SameShortcut(pair.Value,shortcut)){error="快捷键 "+shortcut+" 已分配给 "+ShortcutName(pair.Key)+"，请选择其他按键";return false;}if(hotkeyId==200)foreach(var pair in Options.Items)if(SameShortcut(pair.Value.Shortcut,shortcut)){error="快捷键 "+shortcut+" 已分配给 "+Names[Array.IndexOf(Ids,pair.Key)]+"，请选择其他按键";return false;}}string old;registered.TryGetValue(hotkeyId,out old);if(key!=0&&old!=null&&SameShortcut(old,shortcut))return true;if(!test){if(key!=0){if(!Native.RegisterHotKey(source.Handle,299,mods,key)){error="快捷键 "+shortcut+" 被 Windows 或其他软件占用，原设置保持不变；请换一个快捷键";return false;}Native.UnregisterHotKey(source.Handle,299);}if(!editing){Native.UnregisterHotKey(source.Handle,hotkeyId);if(key!=0&&!Native.RegisterHotKey(source.Handle,hotkeyId,mods,key)){uint oldMods,oldKey;bool restored=Parse(old,out oldMods,out oldKey)&&oldKey!=0&&Native.RegisterHotKey(source.Handle,hotkeyId,oldMods,oldKey);if(hotkeyId==200)ManagerHotkeyRegistered=restored;error="快捷键注册失败，已尝试恢复原设置";return false;}}}if(key==0)registered.Remove(hotkeyId);else registered[hotkeyId]=shortcut;if(hotkeyId==200)ManagerHotkeyRegistered=key!=0&&(test||!editing);return true;}
 string ShortcutName(int id){return id==200?"组件管理":id>=210&&id<210+Ids.Length?Names[id-210]:"其他功能";}
 bool Bind(int index,string shortcut,out string error){return BindKey(210+index,shortcut,out error);}
 public bool ChangeManagerShortcut(string shortcut,out string error){string old=Options.ManagerShortcut;if(!BindKey(200,shortcut,out error))return false;Options.ManagerShortcut=shortcut??"";try{Save();}catch(Exception ex){Options.ManagerShortcut=old;string ignored;BindKey(200,old,out ignored);error="快捷键未保存："+ex.Message;return false;}box.RefreshManagerHint(Options.ManagerShortcut);UpdateSummary();return true;}
 public bool ChangeShortcut(string id,string shortcut,out string error){if(id=="manager")return ChangeManagerShortcut(shortcut,out error);int index=Array.IndexOf(Ids,id);if(index<0){error="组件不存在";return false;}if(!Bind(index,shortcut,out error))return false;Options.Items[id].Shortcut=shortcut;Save();UpdateSummary();return true;}
 IntPtr Hook(IntPtr h,int msg,IntPtr wp,IntPtr lp,ref bool handled){if(msg!=0x312)return IntPtr.Zero;if(wp.ToInt32()==200){ToggleManager();handled=true;}else if(wp.ToInt32()>=210&&wp.ToInt32()<210+Ids.Length){string id=Ids[wp.ToInt32()-210];InvokeShortcut(id);handled=true;}return IntPtr.Zero;}
 void Editing(bool value){if(test||editing==value)return;editing=value;if(value){foreach(int id in registered.Keys)Native.UnregisterHotKey(source.Handle,id);ManagerHotkeyRegistered=false;}else{ManagerHotkeyRegistered=false;foreach(var pair in registered){uint mods,key;if(Parse(pair.Value,out mods,out key)&&key!=0){bool ok=Native.RegisterHotKey(source.Handle,pair.Key,mods,key);if(pair.Key==200)ManagerHotkeyRegistered=ok;if(!ok)Error="有快捷键被其他程序占用，请重新设置";}}}Record();}
