 void CaptureManagerKey(KeyEventArgs e){e.Handled=true;Key key=e.Key==Key.System?e.SystemKey:e.Key;if(key==Key.Escape){Keyboard.ClearFocus();return;}if(new[]{Key.LeftCtrl,Key.RightCtrl,Key.LeftAlt,Key.RightAlt,Key.LeftShift,Key.RightShift}.Contains(key))return;if(Keyboard.Modifiers==ModifierKeys.None&&key!=Key.Back&&key!=Key.Delete&&(key<Key.F1||key>Key.F24)){feedback.Text="请按功能键或带Ctrl / Alt / Shift的组合键";return;}SetManagerInput(key==Key.Back||key==Key.Delete?"":new KeyGestureConverter().ConvertToInvariantString(new KeyGesture(key,Keyboard.Modifiers)));}
