 public static ImageSource ComponentIcon(string id){var group=new DrawingGroup();var pen=new Pen(Brushes.White,1.8){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round,LineJoin=PenLineJoin.Round};using(var dc=group.Open()){switch(id){case "clock":dc.DrawEllipse(null,pen,new Point(16,16),11,11);dc.DrawLine(pen,new Point(16,9),new Point(16,16));dc.DrawLine(pen,new Point(16,16),new Point(22,19));break;case "files":dc.DrawGeometry(null,pen,Geometry.Parse("M3,10 L3,27 L29,27 L29,7 L16,7 L13,4 L3,4 Z"));break;case "panel":dc.DrawRoundedRectangle(null,pen,new Rect(4,5,24,23),3,3);dc.DrawLine(pen,new Point(4,12),new Point(28,12));for(int y=17;y<=23;y+=6)for(int x=10;x<=22;x+=6)dc.DrawRoundedRectangle(Brushes.White,null,new Rect(x-1,y-1,2.5,2.5),.5,.5);break;case "control":for(int row=0;row<3;row++){double y=8+row*8,x=row==1?21:11;dc.DrawLine(pen,new Point(4,y),new Point(28,y));dc.DrawEllipse(new SolidColorBrush(Color.FromRgb(35,55,65)),pen,new Point(x,y),3,3);}break;case "shots":dc.DrawLine(pen,new Point(2,7),new Point(30,7));dc.DrawRoundedRectangle(null,pen,new Rect(6,12,21,16),2,2);dc.DrawLine(pen,new Point(16,5),new Point(16,14));dc.DrawGeometry(null,pen,Geometry.Parse("M8,25 L13,20 L17,23 L22,17 L25,21"));break;default:dc.DrawRoundedRectangle(null,pen,new Rect(2,9,28,17),6,6);for(int x=8;x<=24;x+=8)dc.DrawRoundedRectangle(Brushes.White,null,new Rect(x-2,14,4,6),1,1);break;}}group.Freeze();var image=new DrawingImage(group);image.Freeze();return image;}
