 public void Dispose(){if(disposed)return;disposed=true;if(refresh!=null)refresh.Stop();if(glassSave!=null){if(glassSave.IsEnabled)Save();glassSave.Stop();}if(backdrop!=null)backdrop.Dispose();if(Manager!=null)Manager.Close();if(!test){Native.UnregisterHotKey(source.Handle,200);foreach(int id in registered.Keys)Native.UnregisterHotKey(source.Handle,id);}source.Dispose();}
}
