 foreach(string id in ComponentHub.Ids)hub.SetVisible(id,false);check("所有组件可以分别关闭且管理服务仍存活",ComponentHub.Ids.All(id=>!hub.Enabled(id)&&!hub.WindowFor(id).IsVisible));box.Dock.Hold=new DockHold(box.Dock,true);box.Dock.Hold.SetHeld(true,"disabled dock check");box.Dock.ApplyHoldVisibility();box.MinimizePanel();check("关闭底栏后F6和面板收起不会重新显示底栏",!box.Dock.IsVisible);box.Dock.Hold.Dispose();box.Dock.Hold=null;
 hub.SetVisible("clock",true);check("只打开时间不恢复其他组件",Program.Status.IsVisible&&!box.Dock.IsVisible&&!box.IsVisible&&!control.IsVisible&&!shots.IsVisible);hub.SetVisible("panel",true);hub.SetVisible("control",true);hub.SetVisible("dock",true);shots.Remember(System.Windows.Media.Imaging.BitmapSource.Create(1,1,96,96,PixelFormats.Bgra32,null,new byte[]{60,80,180,255},4));shots.PinRemembered();hub.SetVisible("shots",true);
 bool resize=true;foreach(string id in new[]{"clock","control","shots","dock"}){Window window=hub.WindowFor(id);window.UpdateLayout();double width=window.ActualWidth+23,height=window.ActualHeight+17;var handle=new WindowInteropHelper(window).Handle;Native.SendMessage(handle,0x231,IntPtr.Zero,IntPtr.Zero);window.Width=width;window.Height=height;window.UpdateLayout();Native.SendMessage(handle,0x232,IntPtr.Zero,IntPtr.Zero);window.Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));ComponentSizer.Restore(window,id);window.UpdateLayout();resize&=Math.Abs(hub.Options.Items[id].Width-width)<2&&Math.Abs(window.Width-width)<2&&window.ResizeMode==ResizeMode.CanResize;int hit=ComponentSizer.Hit(window,new Point(3,window.ActualHeight/2));var at=window.PointToScreen(new Point(3,window.ActualHeight/2));long packed=((long)(ushort)(short)at.Y<<16)|(ushort)(short)at.X;resize&=hit==10&&Native.SendMessage(handle,0x84,IntPtr.Zero,new IntPtr(packed)).ToInt32()==10;}check("四个新增组件原生边缘缩放命中且尺寸保存",resize);
 string error;check("自定义快捷键可保存",hub.ChangeShortcut("clock","Ctrl+Shift+F9",out error));check("重复快捷键被拒绝并保留原设置",!hub.ChangeShortcut("panel","Ctrl+Shift+F9",out error)&&hub.Options.Items["panel"].Shortcut=="F5");check("管理键F1及固定F4不能被误占",!hub.ChangeShortcut("clock","F1",out error)&&!hub.ChangeShortcut("clock","F4",out error));uint mods,key;check("不带修饰的字母不会被注册为全局快捷键",!ComponentHub.Parse("A",out mods,out key));check("组件管理默认快捷键为F1",hub.Options.ManagerShortcut=="F1");check("管理快捷键拒绝与组件冲突并保持原设置",!hub.ChangeManagerShortcut("F5",out error)&&hub.Options.ManagerShortcut=="F1");check("管理快捷键可修改并持久化",hub.ChangeManagerShortcut("Ctrl+Shift+F10",out error)&&new JavaScriptSerializer().Deserialize<ComponentOptions>(File.ReadAllText(Path.Combine(Program.S.Root,"components.json"))).ManagerShortcut=="Ctrl+Shift+F10");check("组件不能抢占新的管理快捷键",!hub.ChangeShortcut("panel","Ctrl+Shift+F10",out error));check("F2不再被硬编码保留",hub.ChangeShortcut("files","F2",out error));hub.ChangeShortcut("files","",out error);check("管理快捷键拒绝固定F4",!hub.ChangeManagerShortcut("F4",out error));check("管理快捷键允许清空",hub.ChangeManagerShortcut("",out error)&&hub.Options.ManagerShortcut=="");hub.ChangeManagerShortcut("F1",out error);hub.ToggleManager();check("管理窗口可独立打开",hub.Manager.IsVisible);var overview=AppearanceProbe.Visuals<TextBlock>(hub.Manager).FirstOrDefault(text=>Object.Equals(text.Tag,"shortcut-overview"));check("快捷键总览列出组件及轻按和按住操作",overview!=null&&ComponentHub.Names.All(name=>overview.Text.Contains(name))&&overview.Text.Contains("轻按挂入截图")&&overview.Text.Contains("按住显示")&&overview.Text.Contains("F12"));check("管理窗口提供自身快捷键输入控件",hub.ManagerShortcutInput!=null&&hub.ManagerShortcutInput.Text=="F1");hub.Manager.UpdateLayout();var stableLabels=AppearanceProbe.Visuals<TextBlock>(hub.Manager).Where(text=>Object.Equals(text.Tag,"component-status")).ToArray();bool labelsStable=stableLabels.Length==ComponentHub.Ids.Length;for(int cycle=0;cycle<10;cycle++){hub.Toggle("clock");if(cycle==4)hub.Manager.Width+=12;hub.Manager.UpdateLayout();var currentLabels=AppearanceProbe.Visuals<TextBlock>(hub.Manager).Where(text=>Object.Equals(text.Tag,"component-status")).ToArray();labelsStable&=currentLabels.Length==ComponentHub.Ids.Length&&currentLabels.All(text=>!String.IsNullOrWhiteSpace(text.Text)&&text.ActualHeight>=17)&&stableLabels.Zip(currentLabels,(before,after)=>Object.ReferenceEquals(before,after)).All(same=>same);}check("反复开关与缩放时状态文字保持且控件不被重建",labelsStable);check("管理窗口不再包含框选控件且六个组件均为图标按钮",!AppearanceProbe.Visuals<CheckBox>(hub.Manager).Any()&&AppearanceProbe.Visuals<Button>(hub.Manager).Count(button=>button.Tag is string&&((string)button.Tag).StartsWith("component-toggle:"))==ComponentHub.Ids.Length);var clockToggle=AppearanceProbe.Visuals<Button>(hub.Manager).First(button=>Object.Equals(button.Tag,"component-toggle:clock"));clockToggle.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check("点击组件图标可收起对应组件",!hub.Enabled("clock")&&!Program.Status.IsVisible);clockToggle=AppearanceProbe.Visuals<Button>(hub.Manager).First(button=>Object.Equals(button.Tag,"component-toggle:clock"));clockToggle.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check("再次点击组件图标可打开对应组件",hub.Enabled("clock")&&Program.Status.IsVisible);hub.SetGlass(0);var materialFrame=AppearanceProbe.Visuals<Border>(hub.Manager).First(border=>Object.Equals(border.Tag,"component-manager-frame"));var clearFill=(LinearGradientBrush)materialFrame.Background;check("管理背景0档清透且提供连续玻璃滑条",hub.GlassSlider.Minimum==0&&hub.GlassSlider.Maximum==100&&clearFill.GradientStops.All(stop=>stop.Color.A<=1));hub.SetGlass(100);var frostFill=(LinearGradientBrush)materialFrame.Background;check("管理背景100档提高磨砂表面且滑条同步",hub.GlassSlider.Value==100&&frostFill.GradientStops.All(stop=>stop.Color.A>1));hub.ToggleManager();check("管理窗口可独立收起且组件状态不变",!hub.Manager.IsVisible&&hub.Enabled("clock")&&hub.Enabled("dock"));hub.Save();var restored=new JavaScriptSerializer().Deserialize<ComponentOptions>(File.ReadAllText(Path.Combine(Program.S.Root,"components.json")));check("组件开关快捷键和尺寸独立持久化",restored.Glass==100&&restored.Items["clock"].Shortcut=="Ctrl+Shift+F9"&&restored.Items["clock"].Enabled&&restored.Items["clock"].Width>338);}
 finally{if(Program.Files!=null)Program.Files.Shutdown();Program.Files=previousFiles;Program.Testing=previousTesting;if(hub!=null)hub.Dispose();Program.Components=previousHub;if(shots!=null)shots.Shutdown();if(control!=null){control.PrepareExit();control.Close();}Program.Shots=previousShots;Program.Control=previousControl;}}
