public static class ComponentSizer {
 static readonly Dictionary<Window,bool> resizing=new Dictionary<Window,bool>();
 public static bool Busy(Window window){bool value;return resizing.TryGetValue(window,out value)&&value;}
 public static double Width(string id,double fallback){ComponentOption value;return Program.Components!=null&&Program.Components.Options.Items.TryGetValue(id,out value)&&value.Width>=100?value.Width:fallback;}
 public static double Height(string id,double fallback){ComponentOption value;return Program.Components!=null&&Program.Components.Options.Items.TryGetValue(id,out value)&&value.Height>=60?value.Height:fallback;}
 public static void Restore(Window window,string id){ComponentOption saved;if(Program.Components==null||!Program.Components.Options.Items.TryGetValue(id,out saved)||saved.Width<100||saved.Height<60)return;double w=Width(id,window.Width),h=Height(id,Double.IsNaN(window.Height)?window.ActualHeight:window.Height);if(w>=100&&h>=60&&!Double.IsNaN(w)&&!Double.IsNaN(h)){window.SizeToContent=SizeToContent.Manual;window.Width=Math.Min(window.MaxWidth,Math.Max(window.MinWidth,w));window.Height=Math.Min(window.MaxHeight,Math.Max(window.MinHeight,h));}}
 public static int Hit(Window window,Point p){double w=window.ActualWidth,h=window.ActualHeight;if(window is DockBar&&p.X>=46&&p.X<=w-46&&p.Y>=48&&p.Y<=h-6){p=new Point(p.X-46,p.Y-48);w-=92;h-=54;}double edge=window is StatusWidget?8:14;bool left=p.X>=0&&p.X<edge,right=p.X>w-edge&&p.X<=w,top=p.Y>=0&&p.Y<edge,bottom=p.Y>h-edge&&p.Y<=h;if(left&&top)return 13;if(right&&top)return 14;if(left&&bottom)return 16;if(right&&bottom)return 17;if(left)return 10;if(right)return 11;if(top)return 12;if(bottom)return 15;return 0;}
 public static void Save(Window window,string id){var hub=Program.Components;if(hub==null)return;ComponentOption value;if(!hub.Options.Items.TryGetValue(id,out value))hub.Options.Items[id]=value=new ComponentOption();value.Width=window.ActualWidth;value.Height=window.ActualHeight;hub.Save();}
 public static void Attach(Window window,string id,double minimumWidth,double minimumHeight){window.ResizeMode=ResizeMode.CanResize;window.MinWidth=minimumWidth;window.MinHeight=minimumHeight;window.MaxWidth=SystemParameters.WorkArea.Width-16;window.MaxHeight=SystemParameters.WorkArea.Height-16;resizing[window]=false;Action install=()=>{var source=HwndSource.FromHwnd(new WindowInteropHelper(window).Handle);source.AddHook((IntPtr h,int msg,IntPtr wp,IntPtr lp,ref bool handled)=>{if(msg==0x83||msg==0x85){handled=true;return IntPtr.Zero;}if(msg==0x86){handled=true;return Native.ActivateWithoutFramePaint(h,wp);}if(msg==0x84){long v=lp.ToInt64();int hit=Hit(window,window.PointFromScreen(new Point(unchecked((short)v),unchecked((short)(v>>16)))));if(hit!=0){handled=true;return new IntPtr(hit);}}if(msg==0x231){resizing[window]=true;if(window.SizeToContent!=SizeToContent.Manual){double width=window.ActualWidth,height=window.ActualHeight;window.SizeToContent=SizeToContent.Manual;window.Width=width;window.Height=height;}}if(msg==0x232){resizing[window]=false;window.Dispatcher.BeginInvoke(new Action(()=>{Save(window,id);if(window is DockBar)((DockBar)window).Render();Native.ClipGlass(window,Native.WidgetCornerRadius(window));}),DispatcherPriority.Loaded);}return IntPtr.Zero;});Restore(window,id);};if(new WindowInteropHelper(window).Handle!=IntPtr.Zero)install();else window.SourceInitialized+=(o,e)=>install();window.Closed+=(o,e)=>resizing.Remove(window);}
}
